    CInterfaceMap::SEntry entries[2]; entries[0].type = 0xA7; entries[0].component = &sa; entries[1].type = 0; entries[1].component = 0;
    CThing thing;
    for (int i = 0; i < 9; ++i) thing.UsingComponents[i] = 0;
